8	import hu.bankmonitor.payments.transfers.checks.Verdict;
9	import org.springframework.stereotype.Service;
10	import org.springframework.transaction.annotation.Transactional;
11	
12	/**
13	 * The single place a Transfer's lifecycle advances: one Check answers, and the Transfer
14	 * settles, is rejected, or goes on waiting.
15	 *
16	 * <p>The seam every adapter sits over. Ticket 21 puts an HTTP callback in front of this and
17	 * a broker consumer could replace it later without the domain changing, because nothing here
18	 * knows how the Verdict arrived. Which is also why the refusals below are exceptions rather
19	 * than status codes — {@link UnknownTransferException} and
20	 * {@link TransferNotPendingException} are facts about the Transfer, and the mapping from a
21	 * fact to a response is the adapter's.
22	 *
23	 * <p><b>The order inside {@link #recordVerdict} is the correctness argument</b>, exactly as
24	 * it is in {@link FundsReservation}:
25	 *
26	 * <ol>
27	 * <li>take the row lock on the Transfer, which serialises everything deciding its next
28	 * status;
29	 * <li><em>then</em> read the status, and refuse a Transfer that has already finished;
30	 * <li>answer the Check and ask the ledger what follows;
31	 * <li>on a decision that ends the Transfer, lock both Accounts, claim the transition, and
32	 * move the money.
33	 * </ol>
34	 *
35	 * <p>Step 1 is what makes concurrent Verdicts safe, and it is worth being precise about why,
36	 * because the conditional update in step 4 looks like it should be enough and is not. Two
37	 * Verdicts arriving together each write their own ledger row, and neither transaction can see
38	 * the other's until it commits — so both read a ledger with one Check still outstanding, both
39	 * decide to wait, and the Transfer stays {@code PENDING} for ever against a fully approved
40	 * ledger. Neither transaction ever reaches the update, so no guard on it helps.
41	 * {@link TransferRepository#findAndLockById} is where that argument is written down at
42	 * length.
43	 *
44	 * <p><b>Lock order is Transfer first, then Accounts ascending</b>, and it has to be the same
45	 * everywhere or the ordering buys nothing. It is acyclic against the reservation, which takes
46	 * Account locks only and never waits on a Transfer row that already exists.
47	 *
48	 * <p>Rejection locks both Accounts although only the source moves. That is not an oversight:
49	 * {@link AccountLocking#lockForTransfer} is the whole of what {@code accounts} exports, and
50	 * design decision 30 keeps its repository package-private precisely so there is no second way
51	 * to reach a balance. A lock on an Account nothing writes costs a row lock held for the rest
52	 * of a short transaction, which is cheaper than a second entry point into the slice.
53	 *
54	 * <p>Nothing here saves either Account or the Transfer, for {@link FundsReservation}'s
55	 * reason: the Accounts come back from {@link AccountLocking} attached to this transaction's
56	 * persistence context, so moving the money <em>is</em> the write, and the status moves by a
57	 * guarded update rather than by a mutator {@link Transfer} deliberately does not have.
58	 */
59	@Service
60	class VerdictRecording {
61	
62		private final AccountLocking accounts;
63	
64		private final TransferRepository transfers;
65	
66		private final CheckLedger ledger;
67	
68		VerdictRecording(AccountLocking accounts, TransferRepository transfers, CheckLedger ledger) {
69			this.accounts = accounts;
70			this.transfers = transfers;
71			this.ledger = ledger;
72		}
73	
74		/**
75		 * Records one Check's answer for one Transfer and returns the status the Transfer is in
76		 * once it has been acted on, in one transaction that writes the answer and its
77		 * consequences together or neither.
78		 *
79		 * <p>Together is the requirement rather than a convenience. An answer committed apart from
80		 * the movement it authorises is either a settled Transfer nobody paid or a payment against
81		 * a ledger that does not say why, and {@link CheckLedger#record} states that to the
82		 * container by refusing to run without a transaction of the caller's.
83		 *
84		 * <p><b>A redelivery onto a finished Transfer is refused rather than absorbed.</b> A Check
85		 * service delivers at least once, so the Verdict that settled a Transfer will arrive
86		 * again; it meets the terminal-status refusal in step 2 and never reaches the ledger. What
87		 * makes that safe rather than merely strict is that the money moved once and
88		 * {@link TransferNotPendingException} carries the status, so the caller learns that its
89		 * report landed and what it did. Absorbing the redelivery instead would mean reading the
90		 * ledger before the refusal to find out whether this Check had already given this answer,
91		 * which buys a friendlier response for a longer critical section.
92		 *
93		 * @return {@code PENDING} while any Check is still outstanding, otherwise the terminal
94		 *         status this Verdict moved the Transfer to
95		 * @throws UnknownTransferException     if no Transfer has that ID
96		 * @throws TransferNotPendingException  if the Transfer has already reached a terminal
97		 *                                      status
98		 * @throws hu.bankmonitor.payments.transfers.checks.CheckNotRequiredException if the
99		 *                                      Transfer's ledger has no row for that Check
100		 */
101		@Transactional
102		public TransferStatus recordVerdict(long transferId, Check check, Verdict verdict) {
103			Transfer transfer = transfers.findAndLockById(transferId)
104					.orElseThrow(() -> new UnknownTransferException(transferId));
105			if (transfer.getStatus() != TransferStatus.PENDING) {
106				throw new TransferNotPendingException(transferId, transfer.getStatus());
107			}
108	
109			LedgerDecision decision = ledger.record(transferId, check, verdict);
110			return switch (decision) {
111				case SETTLE -> settle(transfer);
112				case REJECT -> reject(transfer);
113				case WAIT -> TransferStatus.PENDING;
114			};
115		}
116	
117		/**
118		 * The money leaves: the source Account's balance and Reserved Amount both fall, and the
119		 * destination's balance rises. {@link hu.bankmonitor.payments.accounts.Account#settle}
120		 * does both halves of the debit, which is what stops a settled Transfer leaving its
121		 * reservation behind for every later overdraft check to test against.
122		 */
123		private TransferStatus settle(Transfer transfer) {
124			LockedAccounts locked = lock(transfer);
125			claim(transfer, TransferStatus.SETTLED);
126	
127			locked.source().settle(transfer.getDebitedAmount());
128			locked.destination().credit(transfer.getCreditedAmount());
129			return TransferStatus.SETTLED;
130		}
131	
132		/**
133		 * The reservation is given up and no money ever moved, so there is no compensating
134		 * movement to write. That is the payoff of settling asynchronously rather than inside the
135		 * request: "undo a payment" is "do not make one".
136		 */
137		private TransferStatus reject(Transfer transfer) {
138			LockedAccounts locked = lock(transfer);
139			claim(transfer, TransferStatus.REJECTED);
140	
141			locked.source().release(transfer.getDebitedAmount());
142			return TransferStatus.REJECTED;
143		}
144	
145		private LockedAccounts lock(Transfer transfer) {
146			return accounts.lockForTransfer(transfer.getSourceAccountId(), transfer.getDestinationAccountId());
147		}
148	
149		/**
150		 * Takes the transition before acting on it, so that no money moves against a Transfer this
151		 * caller did not move.
152		 *
153		 * <p>Under the row lock taken at the top of {@link #recordVerdict} the guard cannot fail,
154		 * and that is the point of writing it as a guarded update anyway: a future caller that
155		 * reached this without the lock fails loudly here instead of settling a Transfer somebody
156		 * else has already settled.
157		 */
158		private void claim(Transfer transfer, TransferStatus terminalStatus) {
159			if (transfers.advanceFromPending(transfer.getId(), terminalStatus) != 1) {
160				throw new IllegalStateException(
161						"transfer %d was advanced by someone else".formatted(transfer.getId()));
162			}
163		}
164	}
